using System;
using System.IO;
using System.Diagnostics;
using System.Reflection;
using System.Windows.Forms;
using Microsoft.Win32;
class Setup {
 static string self=Assembly.GetExecutingAssembly().Location;
 static string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","WinBoard");
 static bool test;static bool? startupChoice;static string name {get{return test?"WinBoard.Test":"WinBoard";}}
 static string reg {get{return @"Software\Microsoft\Windows\CurrentVersion\Uninstall\"+name;}}
 static void StopApp(){string exe=Path.Combine(target,"WinBoard.exe");if(!File.Exists(exe))return;using(var p=Process.Start(new ProcessStartInfo(exe,"--exit"){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(10000))throw new IOException("请先退出 WinBoard 后再重试。");}System.Threading.Thread.Sleep(700);}
 static string Shortcut(string dir){return Path.Combine(dir,name+".lnk");}
 static void Link(string folder,bool startup=false){Directory.CreateDirectory(folder);Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type);object link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{Shortcut(folder)});Type t=link.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(target,"WinBoard.exe")});t.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{target});t.InvokeMember("IconLocation",BindingFlags.SetProperty,null,link,new object[]{Path.Combine(target,"WinBoard.exe")+",0"});if(startup)t.InvokeMember("Arguments",BindingFlags.SetProperty,null,link,new object[]{"--startup"});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);System.Runtime.InteropServices.Marshal.ReleaseComObject(link);System.Runtime.InteropServices.Marshal.ReleaseComObject(shell);}
 static string menu {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),name);}}
 static void Install(){if(!Environment.Is64BitOperatingSystem)throw new Exception("需要 Windows 10/11 64 位系统。");Directory.CreateDirectory(target);StopApp();string temp=Path.Combine(target,"WinBoard.installing");using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("Payload"))using(var output=File.Create(temp))input.CopyTo(output);string exe=Path.Combine(target,"WinBoard.exe");if(File.Exists(exe))File.Delete(exe);File.Move(temp,exe);File.Copy(self,Path.Combine(target,"Uninstall.exe"),true);Link(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory));Link(menu);if(!test){string startup=Environment.GetFolderPath(Environment.SpecialFolder.Startup);bool wanted=startupChoice??(File.Exists(Shortcut(startup))||Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run","WinBoard",null)!=null);if(wanted)Link(startup,true);else if(File.Exists(Shortcut(startup)))File.Delete(Shortcut(startup));using(var run=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true))if(run!=null)run.DeleteValue("WinBoard",false);}using(var k=Registry.CurrentUser.CreateSubKey(reg)){k.SetValue("DisplayName",name);k.SetValue("DisplayVersion","1.2.0");k.SetValue("Publisher","AdrainLin");k.SetValue("InstallLocation",target);k.SetValue("DisplayIcon",exe);k.SetValue("UninstallString","\""+Path.Combine(target,"Uninstall.exe")+"\" --uninstall"+(test?" --test":""));k.SetValue("NoModify",1);k.SetValue("NoRepair",1);}}
 static void Remove(){StopApp();if(!test){string startup=Shortcut(Environment.GetFolderPath(Environment.SpecialFolder.Startup));if(File.Exists(startup)){object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));object l=shell.GetType().InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{startup});string p=(string)l.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,l,null);System.Runtime.InteropServices.Marshal.ReleaseComObject(l);System.Runtime.InteropServices.Marshal.ReleaseComObject(shell);if(string.Equals(p,Path.Combine(target,"WinBoard.exe"),StringComparison.OrdinalIgnoreCase))File.Delete(startup);}}foreach(string file in new[]{"WinBoard.exe","Uninstall.exe"}){string p=Path.Combine(target,file);if(File.Exists(p))File.Delete(p);}foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),menu}){string l=Shortcut(folder);if(File.Exists(l))File.Delete(l);}if(Directory.Exists(menu)&&Directory.GetFileSystemEntries(menu).Length==0)Directory.Delete(menu);Registry.CurrentUser.DeleteSubKeyTree(reg,false);using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){string command=k==null?null:k.GetValue("WinBoard") as string;if(command!=null&&command.StartsWith("\""+Path.Combine(target,"WinBoard.exe")+"\"",StringComparison.OrdinalIgnoreCase))k.DeleteValue("WinBoard",false);}if(Directory.Exists(target)&&Directory.GetFileSystemEntries(target).Length==0)Directory.Delete(target);}
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();test=Array.IndexOf(args,"--test")>=0;for(int i=0;i<args.Length-1;i++)if(args[i]=="--dir")target=Path.GetFullPath(args[i+1]);try{
 if(Array.IndexOf(args,"--remove")>=0){int index=Array.IndexOf(args,"--wait");if(index>=0)try{Process.GetProcessById(int.Parse(args[index+1])).WaitForExit(10000);}catch{}Remove();return;}
 if(Array.IndexOf(args,"--uninstall")>=0){target=Path.GetDirectoryName(self);if(MessageBox.Show("卸载 WinBoard？个人 data 配置文件夹将保留。","WinBoard",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;string copy=Path.Combine(Path.GetTempPath(),"WinBoard-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(self,copy);Process.Start(copy,"--remove --dir \""+target+"\" --wait "+Process.GetCurrentProcess().Id+(test?" --test":""));return;}
 if(Array.IndexOf(args,"--silent")>=0){Install();return;}
 var form=new Form{Text="安装 WinBoard",Width=490,Height=335,StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false};form.Icon=System.Drawing.Icon.ExtractAssociatedIcon(self);
 form.Controls.Add(new Label{Text="WinBoard 1.2\n开发者 AdrainLin · 开发时间 2024年11月4日",Left=25,Top=25,Width=425,Height=55,Font=new System.Drawing.Font("Microsoft YaHei UI",12)});
 form.Controls.Add(new Label{Text="将为当前用户安装，并创建桌面和开始菜单快捷方式。\n安装位置："+target,Left=25,Top=90,Width=425,Height=65});
 var launch=new CheckBox{Text="安装完成后打开 WinBoard",Checked=true,Left=25,Top=165,Width=400};form.Controls.Add(launch);
 var startupBox=new CheckBox{Text="开机自启动",Checked=true,Left=25,Top=198,Width=400};form.Controls.Add(startupBox);var button=new Button{Text="一键安装",Left=25,Top=240,Width=425,Height=36};button.Click+=(s,e)=>{button.Enabled=false;try{startupChoice=startupBox.Checked;Install();if(launch.Checked)Process.Start(Path.Combine(target,"WinBoard.exe"));MessageBox.Show("安装完成。", "WinBoard");form.Close();}catch(Exception ex){MessageBox.Show(ex.Message,"安装未完成");button.Enabled=true;}};form.Controls.Add(button);Application.Run(form);
 }catch(Exception ex){if(Array.IndexOf(args,"--silent")>=0||Array.IndexOf(args,"--remove")>=0){Console.Error.WriteLine(ex);Environment.ExitCode=1;}else MessageBox.Show(ex.Message,"WinBoard");}}
}
